/*
 * A365849  Triangular numbers that are the product of two distinct prime
 *          numbers of the form 4*k + 3.
 * https://oeis.org/A365849
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth triangular number T_m (m*(m+1)/2) that equals p*q
 *            where p and q are distinct primes of the form 4*k+3. The
 *            sequence is generated by scanning triangular numbers, testing
 *            each for this property
 * Range:     u8 n <= 2, u16 n <= 6, u32 n <= 32, u64 n <= 32, u128 n <= 32,
 *            big any n
 * Helpers:   ensure_capacity
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Standard headers and helper declarations */
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/ensure_capacity.h"   /* ensures dynamic reallocation */

/* Static state shared between calls */
static seq_t *cache = NULL;          /* array of found triangular numbers */
static size_t cache_used = 0;        /* number of terms stored currently */
static size_t cache_cap  = 0;        /* capacity of cache */
static idx_t next_m = 1;             /* next m to examine */

/* Prime list for factorisation */
#define PRIME_LIMIT  6000000          /* sufficient for n up to ~10000   */
static uint32_t *primes = NULL;      /* array of primes up to PRIME_LIMIT */
static size_t prime_cnt = 0;

/* Helper: generate all primes up to PRIME_LIMIT using sieve.
   Only called once at first use. */
static void init_primes(void) {
    if (primes != NULL) return;            /* already initialised */
    size_t lim = PRIME_LIMIT;
    bool *is_comp = (bool *)malloc(lim + 1);
    if (is_comp == NULL) return;           /* out of memory, improbable */
    for (size_t i = 0; i <= lim; ++i) is_comp[i] = false;
    prime_cnt = 0;
    for (size_t i = 2; i <= lim; ++i) {
        if (!is_comp[i]) {
            ++prime_cnt;
            if (i * i <= lim) {
                for (size_t j = i * i; j <= lim; j += i)
                    is_comp[j] = true;
            }
        }
    }
    primes = (uint32_t *)malloc(prime_cnt * sizeof(uint32_t));
    if (primes == NULL) return;           /* out of memory */
    size_t idx = 0;
    for (size_t i = 2; i <= lim; ++i)
        if (!is_comp[i]) primes[idx++] = (uint32_t)i;
    free(is_comp);
}

/* Test whether a given unsigned 64‑bit number T
   is a product of two distinct primes of the form 4*k+3. */
static bool is_23_semiprime(uint64_t T) {
    /* T must be odd (2 cannot appear because 2 ≡ 2 mod 4) */
    if (T % 2 == 0) return false;

    uint64_t tmp = T;
    int distinct = 0;

    /* Ensure primes list is ready */
    init_primes();

    for (size_t i = 0; i < prime_cnt; ++i) {
        uint32_t p = primes[i];
        if ((uint64_t)p * (uint64_t)p > tmp) break;
        if (tmp % p == 0) {
            int exp = 0;
            while (tmp % p == 0) {
                tmp /= p;
                ++exp;
                if (exp > 1) return false;          /* repeated factor */
            }
            if (p % 4 != 3) return false;            /* wrong residue */
            ++distinct;
            if (distinct > 2) return false;           /* more than 2 primes */
        }
    }

    if (tmp > 1) {          /* remaining factor is prime */
        if (tmp % 4 != 3) return false;
        ++distinct;
        if (distinct > 2) return false;
    }

    return distinct == 2;
}

/* Main sequence function required by the framework */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0; /* undefined, but safe default */

    /* Ensure cache has at least n terms */
    while (cache_used < n) {
        uint64_t T = ((uint64_t)next_m * (next_m + 1)) / 2;
        if (is_23_semiprime(T)) {
            /* Grow cache if necessary */
            ensure_capacity(cache_used + 1, &cache_cap, (void **)&cache,
                            sizeof(seq_t));
            cache[cache_used] = (seq_t)T;
            ++cache_used;
        }
        ++next_m;
    }

    return cache[n - 1];
}
